function dateAfterDays(days) { const date = new Date(); date.setHours(12,0,0,0); date.setDate(date.getDate()+days); return toLocalDateKey(date); }
function clockMinutes(value) { const match=String(value||'').trim().match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/i); if(!match)return null; let hours=Number(match[1])%12; if(match[3].toUpperCase()==='PM')hours+=12; const minutes=Number(match[2]||0); if(minutes>59)return null; return hours*60+minutes; }

